// ui-general · кейсы ui-01, ui-02, ui-03, ui-08 (.qa/tests/ui-general/) — תפריט הצד, ניווט, נציג (только чтение)
import { test, expect, Page } from '@playwright/test';
import * as path from 'path';

test.use({ storageState: path.resolve(__dirname, '../../../auth/admin.json') });

const nav = (page: Page) => page.getByRole('complementary').getByRole('navigation');
const navItems = (page: Page) =>
  nav(page).locator('a, button').evaluateAll((els) => els.map((e) => (e as HTMLElement).innerText.trim()));

async function impersonate(page: Page, employee: string) {
  await page.goto('/team');
  await expect(page.getByRole('heading', { name: 'צוות והרשאות' })).toBeVisible();
  const row = page.locator('div').filter({ hasText: employee }).filter({ has: page.getByRole('button', { name: 'פעולות' }) }).last();
  await row.getByRole('button', { name: 'פעולות' }).click();
  await page.getByRole('menuitem', { name: 'כניסה כעובד' }).click();
  await page.getByRole('dialog').getByRole('button', { name: 'כניסה', exact: true }).click();
  await expect(page.getByText(`מחובר/ת כרגע בתור ${employee} — כניסה כעובד פעילה`)).toBeVisible({ timeout: 20_000 });
}

async function backToAdmin(page: Page) {
  await page.getByText('חזרה לחשבון הניהול').click();
  await expect(page.getByText('test admin').first()).toBeVisible({ timeout: 20_000 });
}

test.describe('ui-general — תפריט הצד (מפיץ)', () => {
  test('סדר ושמות הפריטים: «מפה וליקוט» במקום «מלאי», כותרת «קטלוג וניהול» #6a858e15 #6a6755e0 @desktop @prod-safe', async ({ page }) => {
    await page.goto('/dashboard');
    await expect(page.getByRole('heading', { level: 1, name: 'לוח בקרה' })).toBeVisible({ timeout: 20_000 });
    const items = (await navItems(page)).filter((t) => !['מפת המחסן', 'ליקוט וניתוב'].includes(t));
    expect(items).toEqual(['לוח בקרה', 'קטלוג ומלאי', 'מפה וליקוט', 'הזמנות', 'משלוחים', 'לקוחות', 'תמחור', 'צוות והרשאות', 'הגדרות']);
    await expect(nav(page).getByText('מלאי', { exact: true })).toHaveCount(0);
    await nav(page).getByRole('link', { name: 'קטלוג ומלאי' }).click();
    await expect(page).toHaveURL(/\/catalog/);
    await expect(page.getByRole('heading', { level: 1, name: 'קטלוג וניהול' })).toBeVisible();
    await expect(page.getByRole('heading', { level: 1, name: 'מוצרים' })).toHaveCount(0);
  });

  test('כפתור «כיווץ» מכווץ ומרחיב את תפריט הצד #6a6755e0 @desktop @prod-safe', async ({ page }) => {
    await page.goto('/dashboard');
    const aside = page.getByRole('complementary');
    await expect(aside.getByRole('button', { name: 'כיווץ תפריט הצד' })).toBeVisible({ timeout: 20_000 });
    expect((await aside.boundingBox())!.width).toBeGreaterThan(250);
    await aside.getByRole('button', { name: 'כיווץ תפריט הצד' }).click();
    await expect(aside.getByRole('button', { name: 'הרחבת תפריט הצד' })).toBeVisible();
    await expect.poll(async () => (await aside.boundingBox())!.width).toBeLessThan(150);
    await aside.getByRole('button', { name: 'הרחבת תפריט הצד' }).click();
    await expect(aside.getByRole('button', { name: 'כיווץ תפריט הצד' })).toBeVisible();
    await expect.poll(async () => (await aside.boundingBox())!.width).toBeGreaterThan(250);
  });

  test('אין סימן «‹» דקורטיבי; החץ של «מפה וליקוט» פותח תת-תפריט #6a677c6b @desktop @prod-safe', async ({ page }) => {
    await page.goto('/dashboard');
    await expect(nav(page)).toBeVisible({ timeout: 20_000 });
    expect(await nav(page).innerText()).not.toContain('‹');
    const group = nav(page).getByRole('button', { name: 'מפה וליקוט' });
    if ((await group.getAttribute('aria-expanded')) !== 'true') await group.click();
    await expect(group).toHaveAttribute('aria-expanded', 'true');
    await expect(nav(page).getByRole('link', { name: 'מפת המחסן' })).toHaveAttribute('href', '/warehouse/map');
    await expect(nav(page).getByRole('link', { name: 'ליקוט וניתוב' })).toHaveAttribute('href', '/warehouse/picking');
  });

  test('«הגדרות» ו«לוח בקרה» בתפריט מעבירים למסכים שלהם #6a70b4a9 @desktop @prod-safe', async ({ page }) => {
    await page.goto('/catalog');
    await expect(page.getByRole('heading', { level: 1, name: 'קטלוג וניהול' })).toBeVisible({ timeout: 20_000 });
    await nav(page).getByRole('link', { name: 'הגדרות' }).click();
    await expect(page).toHaveURL(/\/settings$/);
    await expect(page.getByRole('heading', { level: 1, name: 'הגדרות' })).toBeVisible();
    await nav(page).getByRole('link', { name: 'לוח בקרה' }).click();
    await expect(page).toHaveURL(/\/dashboard$/);
    await expect(page.getByRole('heading', { level: 1, name: 'לוח בקרה' })).toBeVisible();
  });
});

test.describe('ui-general — נציג מכירות (כניסה כעובד)', () => {
  test('נציג: תפריט לפי הרשאות; לוח בקרה רק ללקוחות שלו — מצב ריק; דוח רו״ח חסום #6a70b4a9 #6a70b2db @desktop', async ({ page }) => {
    await impersonate(page, 'משה כהן');
    expect(await navItems(page)).toEqual(['לוח בקרה', 'הזמנות', 'לקוחות', 'הגדרות']);

    await nav(page).getByRole('link', { name: 'לוח בקרה' }).click();
    await expect(page).toHaveURL(/\/dashboard$/);
    await expect(page.getByRole('heading', { level: 1, name: 'לוח בקרה' })).toBeVisible();
    await expect(page.getByText('הלקוחות שלי')).toBeVisible();
    await expect(page.getByRole('combobox', { name: 'היקף' })).toHaveCount(0);
    // משה כהן без назначенных клиентов → пусто, без цифр компании
    await expect(page.getByText('אין נתונים לתקופה שנבחרה')).toBeVisible({ timeout: 20_000 });
    await expect(page.getByText(/לא נרשמו הזמנות מהלקוחות שהוקצו לך/)).toBeVisible();
    await expect(page.getByText('חוב פתוח')).toHaveCount(0);
    await expect(page.getByRole('heading', { name: 'דוח לרואה חשבון' })).toHaveCount(0);
    await page.getByRole('combobox', { name: 'תקופה' }).selectOption({ label: '90 הימים האחרונים' });
    await expect(page.getByText('אין נתונים לתקופה שנבחרה')).toBeVisible();

    await page.goto('/reports/accounting?from=2026-09-01&to=2026-10-03');
    await expect(page.getByText('שגיאה 403')).toBeVisible({ timeout: 20_000 });

    await page.goto('/orders');
    await backToAdmin(page);
  });

  // rep.json («testtest») — собственная сессия; за ним закреплён клиент «test» (2026-10-04, .qa/context.md). Только чтение.
  test('נציג רואה בלוח הבקרה נתונים של לקוח המשויך אליו בלבד #6a70b2db #6fcb020f @desktop @prod-safe', async ({ browser }) => {
    const ctx = await browser.newContext({ storageState: path.resolve(__dirname, '../../../auth/rep.json'), baseURL: test.info().project.use.baseURL, viewport: { width: 1440, height: 900 } });
    const page = await ctx.newPage();
    try {
      await page.goto('/dashboard');
      await expect(page.getByRole('heading', { level: 1, name: 'לוח בקרה' })).toBeVisible({ timeout: 20_000 });
      expect(await navItems(page)).toEqual(['לוח בקרה', 'הזמנות', 'לקוחות', 'הגדרות']);
      await expect(page.getByText('הלקוחות שלי')).toBeVisible();
      await expect(page.getByRole('combobox', { name: 'היקף' })).toHaveCount(0);
      await page.getByRole('combobox', { name: 'תקופה' }).selectOption({ label: '90 הימים האחרונים' });
      // есть данные закреплённого клиента — не пустое состояние; долг считается по 1 клиенту
      await expect(page.getByText('אין נתונים לתקופה שנבחרה')).toHaveCount(0, { timeout: 20_000 });
      await expect(page.getByText('חוב פתוח')).toBeVisible({ timeout: 20_000 });
      await expect(page.getByText('לקוח אחד', { exact: true })).toBeVisible(); // #6fcb020f: ед. ч. (было «1 לקוחות»)
      await expect(page.getByText('1 לקוחות', { exact: true })).toHaveCount(0);
      // «לקוחות מובילים» — только «test» (других клиентов компании нет)
      const top = page.getByText('לקוחות מובילים', { exact: true }).locator('xpath=ancestor::*[.//*[normalize-space()="test"]][1]');
      await expect(top).toContainText('test');
      for (const other of ['פיצוציה בע\'ם', 'פתח תקווה', 'אלינה בדיקה', 'לקוח מזדמן']) await expect(page.getByText(other)).toHaveCount(0);
      await expect(page.getByRole('heading', { name: 'דוח לרואה חשבון' })).toHaveCount(0);
    } finally {
      await ctx.close();
    }
  });
});
